import base64
from PIL import Image
from io import BytesIO
import os

input_file = 'data:image/png;base64,'
input_file = 'data:image/webp;base64,'

CURRENT_DIR = os.path.dirname(os.path.abspath(__file__))
OCR_BASE_PATH = CURRENT_DIR

def absolute(path):

    if os.path.isabs(path):
        return path

    direct_path = os.path.join(CURRENT_DIR, path)
    if os.path.exists(direct_path):
        return direct_path

    return os.path.join(OCR_BASE_PATH, path)
# ----------------------------------------------------------

def base64_to_png(b64_str, output_path="output.png", width=260, height=80):

    output_path = absolute(output_path)

    # Remove header like: "data:image/png;base64,"
    if "," in b64_str:
        b64_str = b64_str.split(",")[1]

    # Decode base64
    image_data = base64.b64decode(b64_str)
    img = Image.open(BytesIO(image_data))

    # Resize using Pillow new API
    img = img.resize((width, height), Image.Resampling.LANCZOS)

    # Make sure ocr/ exists
    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    img.save(output_path, "PNG")
    return output_path


# Example usage
if __name__ == "__main__":
    base64_to_png(input_file, "output2.png", 60, 60)